require_once __DIR__.'/../includes/bootstrap.php';require_role('Examination Officer','Faculty','Super Admin','College Admin');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){[$exam,$student,$subject,$internal,$practical,$external]=array_map(fn($x)=>(float)$x,[(int)$_POST['exam_id'],(int)$_POST['student_id'],(int)$_POST['subject_id'],$_POST['internal_marks'],$_POST['practical_marks'],$_POST['external_marks']]);$total=$internal+$practical+$external;$pct=$total/(float)$_POST['max_marks']*100;$g=GradeService::grade($pct);$q=db()->prepare('INSERT INTO marks(exam_id,student_id,subject_id,internal_marks,practical_marks,external_marks,total_marks,grade,grade_point,result,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE internal_marks=VALUES(internal_marks),practical_marks=VALUES(practical_marks),external_marks=VALUES(external_marks),total_marks=VALUES(total_marks),grade=VALUES(grade),grade_point=VALUES(grade_point),result=VALUES(result),updated_by=VALUES(updated_by)');$q->execute([$exam,$student,$subject,$internal,$practical,$external,$total,$g['grade'],$g['grade_point'],$pct>=40?'PASS':'FAIL',actor_id()]);AuditService::log('MARKS_UPDATE','results',$student,'Marks updated');$_SESSION['flash']=['success','Marks saved'];redirect('marks.php');}page_top('Marks & Result Engine');flash();?><div class='card p-4'><p>Enter marks through the validated result engine. The grading scale is stored in MySQL and can be changed from system settings.</p><form method='post' class='row g-3'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><div class='col-md-2'><input name='exam_id' type='number' class='form-control' placeholder='Exam ID' required></div><div class='col-md-2'><input name='student_id' type='number' class='form-control' placeholder='Student ID' required></div><div class='col-md-2'><input name='subject_id' type='number' class='form-control' placeholder='Subject ID' required></div><div class='col-md-2'><input name='max_marks' type='number' class='form-control' value='100'></div><div class='col-md-2'><input name='internal_marks' type='number' class='form-control' placeholder='Internal'></div><div class='col-md-2'><input name='practical_marks' type='number' class='form-control' placeholder='Practical'></div><div class='col-md-2'><input name='external_marks' type='number' class='form-control' placeholder='External'></div><div class='col-12'><button class='btn btn-primary'>Save Marks</button></div></form></div><?php page_bottom();